sql.where:
c.delete_flag = 0
and c.status = 1

    and c.contributor_user_id = #{query.contributorUserId}


    and c.resource_type = #{query.resourceType}


    and c.create_time >= #{query.startTime}


    and c.create_time <= #{query.endTime}

mapper.sql:
(
    #{query.baseCoefficient}
    + ifnull(rv.revenue_amount, 0) * #{query.cashRevenueCoefficient}
    + ifnull(rv.point_amount, 0) * #{query.pointRevenueCoefficient}
    + ifnull(m.purchase_count, 0) * #{query.purchaseCoefficient}
    + ifnull(m.view_count, 0) * #{query.viewCoefficient}
    + ifnull(m.collect_count, 0) * #{query.collectCoefficient}
    + ifnull(m.like_count, 0) * #{query.likeCoefficient}
    + ifnull(m.use_count, 0) * #{query.useCoefficient}
)

mapper.select:
select r.id, r.contribution_id as contributionId, c.contributor_user_id as contributorUserId, c.contributor_username as contributorUsername, c.resource_type as resourceType, c.resource_id as resourceId, c.resource_name as resourceName, r.order_id as orderId, r.order_no as orderNo, r.buyer_user_id as buyerUserId, r.revenue_amount as revenueAmount, r.point_amount as pointAmount, r.biz_type as bizType, r.revenue_time as revenueTime from osh_resource_revenue_record r join osh_resource_contribution c on c.id = r.contribution_id
r.delete_flag = 0
and c.contributor_user_id = #{query.contributorUserId}
and c.resource_type = #{query.resourceType}
and r.revenue_time >= #{query.startTime}
and r.revenue_time <= #{query.endTime}
order by r.revenue_time desc, r.id desc
